import os
import sys
import datetime
import pytest

BACKEND_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if BACKEND_DIR not in sys.path:
    sys.path.insert(0, BACKEND_DIR)

from database import User, Event, DepartureLog, DataProvenance, DataSource, SessionLocal, engine
from generator import generate_user_logs
import models

def test_generated_records_are_marked_synthetic(db_session, test_user):
    """Test that all 60 days of logs generated by generator.py are marked synthetic."""
    generate_user_logs(db_session, test_user.id, num_days=10)
    
    logs = db_session.query(DepartureLog).filter(DepartureLog.user_id == test_user.id).all()
    assert len(logs) > 0, "Logs should have been generated"
    
    for log in logs:
        assert log.provenance == DataProvenance.SYNTHETIC.value
        assert log.data_source == DataSource.GENERATOR.value
        assert log.is_synthetic is True
        assert log.recorded_at != ""
        assert log.user_id == test_user.id


def test_simulator_checkout_records_are_marked_real(client, auth_headers, test_user, db_session):
    """Test that actual simulator checkout records are marked real with proper provenance."""
    event = db_session.query(Event).filter(Event.user_id == test_user.id).first()
    
    checkout_payload = {
        "event_id": event.id,
        "event_name": event.name,
        "date": "2026-11-16",
        "day_of_week": "Monday",
        "planned_prep_start": "08:15:00",
        "planned_departure": "08:40:00",
        "estimated_prep_duration_min": 25.0,
        "estimated_travel_duration_min": 20.0,
        "actual_prep_start": "08:16:00",
        "actual_departure": "08:48:00",
        "actual_arrival": "09:08:00",
        "actual_prep_duration_min": 32.0,
        "actual_travel_duration_min": 20.0,
        "bag_prepared": True,
        "tag_one_last_task": True,
        "tag_finding_items": False,
        "tag_phone_usage": False,
        "tag_waiting": False
    }

    response = client.post("/api/checkout", json=checkout_payload, headers=auth_headers)
    assert response.status_code == 200
    res_data = response.json()
    assert res_data["success"] is True
    assert res_data["provenance"] == "real"
    assert res_data["is_synthetic"] is False

    # Check in DB
    created_log = db_session.query(DepartureLog).filter(DepartureLog.id == res_data["log_id"]).first()
    assert created_log is not None
    assert created_log.provenance == DataProvenance.REAL.value
    assert created_log.data_source == DataSource.SIMULATOR_CHECKOUT.value
    assert created_log.is_synthetic is False
    assert created_log.user_id == test_user.id


def test_real_only_training_excludes_synthetic_observations(db_session, test_user):
    """Test that real_only mode trains exclusively on genuine observations."""
    # 1. Add 10 synthetic records
    for i in range(10):
        synth_log = DepartureLog(
            user_id=test_user.id,
            event_name="Synth Event",
            date=f"2026-10-{i+1:02d}",
            day_of_week="Monday",
            planned_prep_start="08:00:00",
            planned_departure="08:20:00",
            estimated_prep_duration_min=20.0,
            estimated_travel_duration_min=20.0,
            actual_prep_start="08:00:00",
            actual_departure="08:25:00",
            actual_arrival="08:45:00",
            actual_prep_duration_min=25.0,
            actual_travel_duration_min=20.0,
            total_delay_min=5.0,
            bag_prepared=True,
            provenance=DataProvenance.SYNTHETIC.value,
            data_source=DataSource.GENERATOR.value,
            is_synthetic=True
        )
        db_session.add(synth_log)

    # 2. Add 9 real records
    for i in range(9):
        real_log = DepartureLog(
            user_id=test_user.id,
            event_name="Real Event",
            date=f"2026-11-{i+1:02d}",
            day_of_week="Tuesday",
            planned_prep_start="08:00:00",
            planned_departure="08:20:00",
            estimated_prep_duration_min=20.0,
            estimated_travel_duration_min=20.0,
            actual_prep_start="08:00:00",
            actual_departure="08:30:00",
            actual_arrival="08:50:00",
            actual_prep_duration_min=30.0,
            actual_travel_duration_min=20.0,
            total_delay_min=10.0,
            bag_prepared=False,
            provenance=DataProvenance.REAL.value,
            data_source=DataSource.SIMULATOR_CHECKOUT.value,
            is_synthetic=False
        )
        db_session.add(real_log)
    db_session.commit()

    # Query df for real_only
    df_real = models.get_logs_df(db_session, test_user.id, training_mode="real_only")
    assert len(df_real) == 9
    assert all(df_real["is_synthetic"] == 0)
    assert all(df_real["provenance"] == "real")
    assert all(df_real["event_name"] == "Real Event")

    # Train in real_only mode
    result = models.train_and_evaluate(db_session, test_user.id, training_mode="real_only")
    assert result["success"] is True
    assert result["training_mode"] == "real_only"
    assert result["is_personalized_real"] is True
    assert result["training_samples_used"] == 9
    assert result["real_samples"] == 9
    assert result["synthetic_samples"] == 10


