def test_generator_preserves_real_records_on_reseed(db_session, test_user):
    """Test that re-generating synthetic logs never deletes genuine user observations."""
    # Ensure a real log exists
    real_log = DepartureLog(
        user_id=test_user.id,
        event_name="Genuine Lab",
        date="2026-11-15",
        day_of_week="Sunday",
        planned_prep_start="08:00:00",
        planned_departure="08:20:00",
        estimated_prep_duration_min=20.0,
        estimated_travel_duration_min=20.0,
        actual_prep_start="08:00:00",
        actual_departure="08:22:00",
        actual_arrival="08:42:00",
        actual_prep_duration_min=22.0,
        actual_travel_duration_min=20.0,
        total_delay_min=2.0,
        provenance=DataProvenance.REAL.value,
        data_source=DataSource.SIMULATOR_CHECKOUT.value,
        is_synthetic=False
    )
    db_session.add(real_log)
    db_session.commit()
    real_log_id = real_log.id

    # Re-run generator for this user
    generate_user_logs(db_session, test_user.id, num_days=5)

    # Check that real log is still present
    preserved_log = db_session.query(DepartureLog).filter(DepartureLog.id == real_log_id).first()
    assert preserved_log is not None, "Real observation was deleted by generator!"
    assert preserved_log.is_synthetic is False
    assert preserved_log.provenance == DataProvenance.REAL.value


def test_data_summary_endpoint(client, auth_headers, test_user, db_session):
    """Test the /api/data-summary endpoint returns accurate counts and model status."""
    response = client.get("/api/data-summary", headers=auth_headers)
    assert response.status_code == 200
    data = response.json()
    assert "real_samples" in data
    assert "synthetic_samples" in data
    assert "total_samples" in data
    assert "has_real_data" in data
    assert data["total_samples"] == data["real_samples"] + data["synthetic_samples"] + data["unknown_samples"]


def test_existing_accounts_continue_working():
    """Verify that the existing production database (backend/microdelay.db) demo users work and have synthetic provenance."""
    db = SessionLocal()
    try:
        users = db.query(User).filter(User.username.in_([
            'student_demo', 'teacher_demo', 'professor_demo', 'engineer_demo'
        ])).all()
        assert len(users) >= 4, "Demo users should exist in the database"

        for u in users:
            counts = models.get_user_data_counts(db, u.id)
            assert counts["synthetic_samples"] > 0, f"Demo user {u.username} should have synthetic logs"
            
            # Test that logs query works and exposes provenance
            logs = db.query(DepartureLog).filter(DepartureLog.user_id == u.id).limit(5).all()
            for l in logs:
                assert l.provenance == "synthetic"
                assert l.is_synthetic is True
                assert l.data_source == "generator"

            # Test that predicting delay still works
            pred = models.predict_micro_delay(
                user_id=u.id,
                event_name="ML Lab",
                day_of_week="Monday",
                importance="high",
                bag_prepared=True,
                estimated_prep_duration_min=20.0,
                estimated_travel_duration_min=20.0
            )
            assert "predicted_delay_min" in pred
            assert pred["predicted_delay_min"] >= 0
    finally:
        db.close()
